-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Phase 3 session integrity (forward-only): freeze the session teacher roster
-- once attendance exists so historical "taught by" provenance cannot be
-- rewritten; editing title/times no longer re-validates an unchanged roster.
-- Also drops the dead events branch from validate_teacher_reference() (the
-- events table was renamed in Phase 2; the trigger now serves
-- teacher_assignments and learner_progress only).
BEGIN;

CREATE OR REPLACE FUNCTION lms.validate_teacher_reference()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  IF TG_TABLE_NAME = 'teacher_assignments' THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('admin', 'super_admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'teacher_assignments.teacher_id must reference an active teacher';
    END IF;
  ELSIF TG_TABLE_NAME = 'learner_progress' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM lms.users
      WHERE id = NEW.teacher_id
        AND role IN ('admin', 'super_admin')
        AND is_active = TRUE
        AND deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'learner_progress.teacher_id must reference an active teacher/admin';
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'learner_progress' AND NEW.teacher_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM lms.users WHERE id = NEW.teacher_id AND role = 'super_admin')
      AND NOT EXISTS (SELECT 1 FROM lms.module_teaching_permissions
        WHERE user_id = NEW.teacher_id AND module_id = NEW.module_id) THEN
      RAISE EXCEPTION 'Selected Admin does not have teaching permission for this module';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION lms.update_curriculum_session(target_session_id uuid, session_title text,
  session_starts_at timestamptz, session_ends_at timestamptz, teacher_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  previous_teachers uuid[];
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status = 'cancelled' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cancelled sessions cannot be edited';
  END IF;
  PERFORM lms_private.validate_session_details(session_title, session_starts_at, session_ends_at);
  SELECT coalesce(array_agg(admin_id ORDER BY admin_id), '{}') INTO previous_teachers
  FROM lms.session_teachers WHERE session_id = target.id;

  UPDATE lms.curriculum_sessions
  SET title = btrim(session_title), starts_at = session_starts_at, ends_at = session_ends_at
  WHERE id = target.id;
  -- Provenance invariant: once attendance exists the teacher roster is frozen,
  -- because completions already credit these teachers. An unchanged roster is
  -- not re-validated, so titles/times stay editable after a grant is revoked.
  IF (SELECT coalesce(array_agg(DISTINCT t ORDER BY t), '{}') FROM unnest(teacher_ids) t) IS DISTINCT FROM previous_teachers THEN
    IF EXISTS (SELECT 1 FROM lms.session_attendances WHERE session_id = target.id) THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = 'Session teachers cannot be changed after attendance has been recorded';
    END IF;
    PERFORM lms_private.replace_session_teachers(target.id, target.module_id, teacher_ids, auth.uid());
  END IF;
  -- Keep the live QR usable: its window follows the session's new times.
  IF session_starts_at IS DISTINCT FROM target.starts_at OR session_ends_at IS DISTINCT FROM target.ends_at THEN
    UPDATE lms.session_qr_tokens
    SET valid_from = session_starts_at - lms_private.session_checkin_grace(),
        expires_at = session_ends_at + lms_private.session_checkin_grace()
    WHERE session_id = target.id AND revoked_at IS NULL;
  END IF;

  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'session_updated', 'curriculum_sessions', target.id, jsonb_build_object(
    'session_id', target.id, 'module_id', target.module_id,
    'previous', jsonb_build_object('title', target.title, 'starts_at', target.starts_at,
      'ends_at', target.ends_at, 'teacher_ids', to_jsonb(previous_teachers)),
    'current', jsonb_build_object('title', btrim(session_title), 'starts_at', session_starts_at,
      'ends_at', session_ends_at, 'teacher_ids', to_jsonb(teacher_ids))));
END;
$$;

COMMIT;
